#include "model.hpp"
#include <algorithm>
bool Board::apply(int command) {
  if (command == 0) { if (done_.size() == 8) return false; done_.push_back(false); return true; }
  if (command < 1 || command > int(done_.size())) return false;
  done_[command - 1] = true; return true;
}
int Board::count() const { return int(done_.size()); }
int Board::done() const { return int(std::count(done_.begin(), done_.end(), true)); }
